export const WEATHERTOP_STEPS=Object.freeze(['climb','summit','defend','escape','complete']);
export const WEATHERTOP_POINTS=Object.freeze({entry:{x:0,z:-41},summit:{x:0,z:6},fire:{x:0,z:11},exit:{x:0,z:-41},return:{x:-42,z:-42}});
export const freshWeathertop=()=>({stage:'climb',defense:0});
export function restoreWeathertop(v){if(!WEATHERTOP_STEPS.includes(v?.stage))return freshWeathertop();return {stage:v.stage,defense:v.stage==='defend'&&Number.isFinite(v.defense)?Math.max(0,Math.min(6,v.defense)):0};}
const near=(p,q,r)=>Number.isFinite(p?.x)&&Number.isFinite(p?.z)&&Math.hypot(p.x-q.x,p.z-q.z)<r;
export function weathertopObjective(s){return ({climb:'اصعد الطريق الحجري إلى قمة ويذرتوب وافحص أطلال برج المراقبة.',summit:'اقترب من موضع النار القديمة؛ ظلال الفرسان تقترب من التل.',defend:'أشعل النار وابقَ قريبًا منها وثابتًا حتى تتراجع الظلال.',escape:'تراجعت الظلال. انزل عبر الطريق الجنوبي واجتمع برفاقك عند الممر.',complete:'نجوت من هجوم ويذرتوب. الطريق التالي نحو Rivendell.'})[s?.stage]||'تابع الطريق.';}
export function weathertopInteraction(s,p){if(!s)return null;if(s.stage==='climb'&&near(p,WEATHERTOP_POINTS.summit,3.8))return {id:'weathertop-summit',name:'افحص أطلال ويذرتوب'};if(s.stage==='summit'&&near(p,WEATHERTOP_POINTS.fire,2.8))return {id:'weathertop-fire',name:'أشعل النار القديمة'};if(s.stage==='escape'&&near(p,WEATHERTOP_POINTS.exit,3.5))return {id:'weathertop-exit',name:'تابع الطريق جنوبًا'};if(s.stage!=='complete'&&near(p,WEATHERTOP_POINTS.return,3.5))return {id:'weathertop-return',name:'عد إلى بري'};return null;}
export function drawWeathertopMap(canvas,p,s){const c=canvas.getContext('2d');if(!c)return;const w=canvas.width,h=canvas.height,xy=q=>({x:40+(q.x+49)/98*(w-80),y:35+(49-q.z)/98*(h-70)});c.clearRect(0,0,w,h);c.fillStyle='#62665f';c.fillRect(0,0,w,h);c.fillStyle='#777b6c';c.beginPath();c.ellipse(w/2,h*.43,w*.28,h*.29,0,0,Math.PI*2);c.fill();c.strokeStyle='#b6a98b';c.lineWidth=12;c.beginPath();for(let z=-38,i=0;z<=6;z+=5,i++){const q=xy({x:Math.sin(i*.42)*1.2,z});i?c.lineTo(q.x,q.y):c.moveTo(q.x,q.y);}c.stroke();c.font='bold 15px Tahoma';c.textAlign='center';for(const [n,q]of [['المدخل',WEATHERTOP_POINTS.entry],['الأطلال',WEATHERTOP_POINTS.summit],['النار',WEATHERTOP_POINTS.fire]]){const v=xy(q);c.fillStyle='#eee2c4';c.beginPath();c.arc(v.x,v.y,6,0,Math.PI*2);c.fill();c.fillText(n,v.x,v.y-12);}if(p){const v=xy(p);c.fillStyle='#e3bd68';c.beginPath();c.arc(v.x,v.y,9,0,Math.PI*2);c.fill();}}
